    OR sdl5.ITEM_VALUE like '%' || #{search} || '%'
    OR sdl6.ITEM_VALUE like '%' || #{search} || '%'
    OR sdl7.ITEM_VALUE like '%' || #{search} || '%'
    OR t.entrustId like '%' || #{search} || '%'
    OR t.invManagerId like '%' || #{search} || '%'
    OR t.invManagerName like '%' || #{search} || '%'
    OR t.realName like '%' || #{search} || '%'
    OR t.trader like '%' || #{search} || '%'
    OR t.portfolioId like '%' || #{search} || '%'
    OR t.portfolioName like '%' || #{search} || '%'
    OR t.finprodMarketId like '%' || #{search} || '%'
    OR t.finprodAbbr like '%' || #{search} || '%'
    OR t.remark like '%' || #{search} || '%'
    OR t.secAcctId like '%' || #{search} || '%'
    OR t.entrustAmt||'' = #{search}
    OR t.etrPrice||'' = #{search}
    OR t.termDays||'' = #{search}
    OR t.exeProgress||'' = #{search}
    OR t.dealProgress||'' = #{search}
