SELECT decode(tpdp.is_cancel,'Y',#{TRADE_FLOW_STATUS03},#{TRADE_FLOW_STATUS02}) effectFlag,
FROM REG_FIN_PRODUCT_DEAL tpdp LEFT JOIN ETR_ENTRUST EE ON EE.entrust_id = tpdp.entrust_id LEFT JOIN ETR_ENTRUST_ADD EEA ON EE.entrust_id = EEA.entrust_id LEFT JOIN PTL_PORTFOLIO pp ON tpdp.portfolio_id = pp.portfolio_id LEFT JOIN FIN_PRODUCT fp ON tpdp.finprod_id = fp.finprod_id LEFT JOIN STL_SEC_ACCT_INFO ssai ON tpdp.sec_manage_acct_id = ssai.SEC_ACCT_ID LEFT JOIN MST_COUNTER_PARTY mcp ON tpdp.COUNTER_ID = mcp.counter_id LEFT JOIN MST_CFETS_CUSTOMER_TRADER mcct ON tpdp.COUNTER_TRADER= mcct.trader_id LEFT JOIN REG_TRADE_FEE ttft ON tpdp.trade_id = ttft.trade_id AND ttft.fee_type =#{feeType06} LEFT JOIN REG_TRADE_FEE ttft1 ON tpdp.trade_id = ttft1.trade_id AND ttft1.fee_type =#{feeType08} LEFT JOIN FIN_EXERCISE_PLAN T6 ON tpdp.FINPROD_ID = T6.FINPROD_ID AND T6.EXERCISE_TYPE ='02' LEFT JOIN ETR_FINISH_STATUS EFS ON EFS.ENTRUST_ID = tpdp.ENTRUST_ID WHERE tpdp.entrust_id = #{entrustId}
union all
SELECT #{TRADE_FLOW_STATUS01} effectFlag,
FROM WFL_REG_FIN_PRODUCT_DEAL tpdp LEFT JOIN ETR_ENTRUST EE ON EE.entrust_id = tpdp.entrust_id LEFT JOIN ETR_ENTRUST_ADD EEA ON EE.entrust_id = EEA.entrust_id LEFT JOIN PTL_PORTFOLIO pp ON tpdp.portfolio_id = pp.portfolio_id LEFT JOIN FIN_PRODUCT fp ON tpdp.finprod_id = fp.finprod_id LEFT JOIN STL_SEC_ACCT_INFO ssai ON tpdp.sec_manage_acct_id = ssai.SEC_ACCT_ID LEFT JOIN MST_COUNTER_PARTY mcp ON tpdp.COUNTER_ID = mcp.counter_id LEFT JOIN MST_CFETS_CUSTOMER_TRADER mcct ON tpdp.COUNTER_TRADER= mcct.trader_id LEFT JOIN WFL_REG_TRADE_FEE ttft ON tpdp.trade_id = ttft.trade_id AND ttft.fee_type =#{feeType06} LEFT JOIN WFL_REG_TRADE_FEE ttft1 ON tpdp.trade_id = ttft1.trade_id AND ttft1.fee_type =#{feeType08} LEFT JOIN FIN_EXERCISE_PLAN T6 ON tpdp.FINPROD_ID = T6.FINPROD_ID AND T6.EXERCISE_TYPE ='02' LEFT JOIN ETR_FINISH_STATUS EFS ON EFS.ENTRUST_ID = tpdp.ENTRUST_ID WHERE tpdp.entrust_id = #{entrustId}
